'// Greeting',
'',
'const hour = new Date().getHours();',
'',
'let greet="";',
'',
'if(hour<12){',
'',
unistr('greet="\2600\FE0F Good Morning";'),
'',
'}',
'else if(hour<17){',
'',
unistr('greet="\D83C\DF24\FE0F Good Afternoon";'),
'',
'}',
'else{',
'',
unistr('greet="\D83C\DF19 Good Evening";'),
'',
'}',
'',
'document.getElementById("greeting").innerHTML =',
'greet + ", Welcome Back!";',
'',
'// Date',
'',
'const options={',
'weekday:''long'',',
'year:''numeric'',',
'month:''long'',',
'day:''numeric''',
'};',
'',
'document.getElementById("currentDate").innerHTML=',
'new Date().toLocaleDateString(''en-US'',options);',
