'// Hero Animation',
'',
'const hero=document.querySelector(".hero-banner");',
'',
'hero.style.opacity=0;',
'hero.style.transform="translateY(40px)";',
'',
'setTimeout(function(){',
'',
'hero.style.transition=".8s";',
'',
'hero.style.opacity=1;',
'',
'hero.style.transform="translateY(0px)";',
'',
