 p_id=>wwv_flow_imp.id(15962366993162413850)
,p_plug_name=>'Attrition'
,p_static_id=>'attrition'
,p_region_css_classes=>'kpi-card'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>60
,p_plug_new_grid_row=>false
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_leave NUMBER;',
'    v_total NUMBER;',
'    v_rate  NUMBER;',
'BEGIN',
'    SELECT COUNT(*)',
'    INTO v_leave',
'    FROM PREDICTIONS',
'    WHERE PREDICTION = ''Leave'';',
'',
'    SELECT COUNT(*)',
'    INTO v_total',
'    FROM EMPLOYEE;',
'',
'    IF v_total = 0 THEN',
'        v_rate := 0;',
'    ELSE',
'        v_rate := ROUND((v_leave / v_total) * 100, 2);',
'    END IF;',
'',
'    HTP.P(''',
'        <div class="kpi-card danger">',
unistr('            <div class="kpi-icon">\D83D\DCC9</div>'),
'            <div class="kpi-value">'' || v_rate || ''%</div>',
'            <div class="kpi-title">Attrition Rate</div>',
'        </div>',
'    '');',
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_created_on=>wwv_flow_imp.dz('20260709085038Z')
,p_updated_on=>wwv_flow_imp.dz('20260727095002Z')
,p_created_by=>'FATIMAASIFKHAN7@GMAIL.COM'
,p_updated_by=>'FATIMAASIFKHAN7@GMAIL.COM'
);
