prompt --application/pages/page_00003
begin
wwv_flow_imp_page.create_page(
 p_id=>3
,p_name=>'Employee Prediction'
,p_alias=>'EMPLOYEE-PREDICTION'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* ==========================================================================',
unistr('   Employee Attrition Prediction \2014 Verdict Hero + Gauge Logic'),
unistr('   Paste into: Page Designer \2192 Page \2192 "JavaScript" \2192 "Function and'),
'   Global Variable Declaration" (or a Dynamic Action "Execute JavaScript',
'   Code" that fires on Page Load / after the Predict button''s AJAX success).',
'',
'   REQUIRES the "Prediction Result" region to have CSS Classes = predictionCard',
'   (see the matching CSS file''s header comment for the one-time setup step).',
'   ========================================================================== */',
'',
'(function () {',
'',
'  function findContainer() {',
'    // Class-based (confirmed working regardless of region template)',
'    var el = document.querySelector(''.predictionCard'');',
'    if (el) return el;',
'    // Fallbacks, harmless to keep in case Static ID ever does render',
'    return document.getElementById(''predictionCard'')',
'        || document.querySelector(''[data-otel-label="predictionCard"]'');',
'  }',
'',
'  function renderVerdict() {',
'    var container = findContainer();',
unistr('    if (!container) return; // Prediction Result region not found \2014 check CSS Classes setup'),
'',
'    // Create the hero banner if it doesn''t already exist',
'    var predEl = document.getElementById(''verdictHero'');',
'    if (!predEl) {',
'      predEl = document.createElement(''div'');',
'      predEl.id = ''verdictHero'';',
'      predEl.className = ''verdict-hero'';',
'      predEl.innerHTML =',
'        ''<div class="verdict-icon"></div>'' +',
'        ''<div class="verdict-text"></div>'' +',
'        ''<div class="verdict-sub"></div>'' +',
unistr('        ''<span class="sparkle">\2726</span>'' +'),
unistr('        ''<span class="sparkle">\2727</span>'' +'),
unistr('        ''<span class="sparkle">\2726</span>'' +'),
unistr('        ''<span class="sparkle">\2727</span>'';'),
'    //   container.insertBefore(predEl, container.firstChild);',
'        var heroContainer = document.getElementById("predictionHeroContainer");',
'',
'if (heroContainer && !heroContainer.contains(predEl)) {',
'    heroContainer.appendChild(predEl);',
'}',
'    }',
'',
'    var prediction = ($v(''P3_PREDICTION'') || '''').trim().toLowerCase();',
'    if (!prediction) return; // no prediction run yet, keep hero hidden',
'',
'    var probability = $v(''P3_PROBABILITY'') || '''';',
'    var risk         = $v(''P3_RISK_LEVEL'') || '''';',
'',
'    var iconEl = predEl.querySelector(''.verdict-icon'');',
'    var textEl = predEl.querySelector(''.verdict-text'');',
'    var subEl  = predEl.querySelector(''.verdict-sub'');',
'',
'    predEl.classList.remove(''verdict-stay'', ''verdict-leave'');',
'    predEl.classList.add(''is-visible'');',
'',
'    if (prediction === ''stay'') {',
'      predEl.classList.add(''verdict-stay'');',
unistr('      iconEl.textContent = ''\D83C\DF89'';'),
'      textEl.textContent = ''STAYING'';',
unistr('      subEl.textContent = ''Low flight risk \2014 probability '' + probability + ''% \00B7 Risk level: '' + risk;'),
'      spawnConfetti(predEl);',
'    } else {',
'      predEl.classList.add(''verdict-leave'');',
unistr('      iconEl.textContent = ''\26A0\FE0F'';'),
'      textEl.textContent = ''AT RISK'';',
unistr('      subEl.textContent = ''This employee may leave \2014 probability '' + probability + ''% \00B7 Risk level: '' + risk;'),
'      spawnRain(predEl);',
'    }',
'',
'    // Optional: color the gauge if you''re using the .gauge markup',
'    var gauge = container.querySelector(''.gauge'');',
'    if (gauge) {',
'      gauge.style.setProperty(''--pct'', parseFloat(probability) || 0);',
'      gauge.classList.remove(''gauge--stay'', ''gauge--leave'');',
'      gauge.classList.add(prediction === ''stay'' ? ''gauge--stay'' : ''gauge--leave'');',
'    }',
'  }',
'',
'  function spawnConfetti(hero) {',
'    for (var i = 0; i < 24; i++) {',
'      var piece = document.createElement(''span'');',
'      piece.className = ''confetti-piece'';',
'      piece.style.left = Math.random() * 100 + ''%'';',
'      piece.style.animationDelay = (Math.random() * 0.4) + ''s'';',
'      hero.appendChild(piece);',
'      (function (p) {',
'        setTimeout(function () { p.remove(); }, 3200);',
'      })(piece);',
'    }',
'  }',
'',
'  function spawnRain(hero) {',
'    for (var i = 0; i < 14; i++) {',
'      var drop = document.createElement(''span'');',
'      drop.className = ''raindrop'';',
'      drop.style.left = Math.random() * 100 + ''%'';',
'      drop.style.animationDelay = (Math.random() * 1.2) + ''s'';',
'      hero.appendChild(drop);',
'      (function (d) {',
'        setTimeout(function () { d.remove(); }, 3000);',
'      })(drop);',
'    }',
'  }',
'',
'  // Run on load (in case a prediction is already populated),',
'  // and expose globally so it can also be called from the Predict',
'  // button''s Dynamic Action "Execute JavaScript Code" success step.',
'  window.renderAttritionVerdict = renderVerdict;',
'  document.addEventListener(''DOMContentLoaded'', renderVerdict);',
'',
'})();',
''))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* ==========================================================================',
unistr('   Verdict Hero \2014 trigger logic'),
unistr('   Paste this into: Page Designer \2192 Page (top of tree) \2192 right panel \2192'),
unistr('   "JavaScript" section \2192 "Execute when Page Loads" field.'),
'   ========================================================================== */',
'',
'(function () {',
'  var container = document.getElementById(''predictionCard'');',
'  if (!container) return; // Prediction Result region not found',
'',
'  // Create the hero banner if it doesn''t already exist',
'  var predEl = document.getElementById(''verdictHero'');',
'  if (!predEl) {',
'    predEl = document.createElement(''div'');',
'    predEl.id = ''verdictHero'';',
'    predEl.className = ''verdict-hero'';',
'    predEl.innerHTML =',
'      ''<div class="verdict-icon"></div>'' +',
'      ''<div class="verdict-text"></div>'' +',
'      ''<div class="verdict-sub"></div>'';',
'    container.insertBefore(predEl, container.firstChild);',
'  }',
'',
'  var prediction = ($v(''P3_PREDICTION'') || '''').trim().toLowerCase();',
'  if (!prediction) return; // no prediction run yet, keep hero hidden',
'',
'  var probability = $v(''P3_PROBABILITY'') || '''';',
'  var risk        = $v(''P3_RISK_LEVEL'') || '''';',
'',
'  var iconEl = predEl.querySelector(''.verdict-icon'');',
'  var textEl = predEl.querySelector(''.verdict-text'');',
'  var subEl  = predEl.querySelector(''.verdict-sub'');',
'',
'  predEl.classList.remove(''verdict-stay'', ''verdict-leave'');',
'',
'  if (prediction === ''stay'') {',
'    predEl.classList.add(''verdict-stay'', ''is-visible'');',
unistr('    iconEl.textContent = ''\D83C\DF89'';'),
'    textEl.textContent = ''Likely to Stay'';',
unistr('    subEl.textContent  = probability + ''% confidence \00B7 '' + risk + '' risk'';'),
'    launchConfetti(predEl);',
'  } else if (prediction === ''leave'') {',
'    predEl.classList.add(''verdict-leave'', ''is-visible'');',
unistr('    iconEl.textContent = ''\26A0\FE0F'';'),
'    textEl.textContent = ''At Risk of Leaving'';',
unistr('    subEl.textContent  = probability + ''% confidence \00B7 '' + risk + '' risk'';'),
'  } else {',
'    predEl.classList.add(''is-visible'');',
'    iconEl.textContent = '''';',
'    textEl.textContent = prediction;',
'    subEl.textContent  = '''';',
'  }',
'',
'  function launchConfetti(container) {',
'    if (window.matchMedia(''(prefers-reduced-motion: reduce)'').matches) return;',
'    var colors = [''#FFD166'', ''#FFFFFF'', ''#7BE0B4'', ''#FFB4B4'', ''#B4D8FF''];',
'    for (var i = 0; i < 24; i++) {',
'      var piece = document.createElement(''span'');',
'      piece.className = ''confetti-piece'';',
'      piece.style.left = Math.random() * 100 + ''%'';',
'      piece.style.background = colors[Math.floor(Math.random() * colors.length)];',
'      piece.style.animationDelay = (Math.random() * 0.4) + ''s'';',
'      piece.style.animationDuration = (2 + Math.random() * 1.2) + ''s'';',
'      container.appendChild(piece);',
'      (function (p) {',
'        setTimeout(function () { p.remove(); }, 4000);',
'      })(piece);',
'    }',
'  }',
'',
'  buildMetricsGrid(container, prediction);',
'',
'  function buildMetricsGrid(container, prediction) {',
'    // Hide APEX''s default rendering for each of these items (whatever',
unistr('    // wrapper class the theme uses \2014 we climb up a few levels generically)'),
