'   ========================================================================== */',
'',
'@import url(''https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700;800&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@500;700&display=swap'');',
'',
':root{',
