'}',
'',
'body, .t-Body{',
'  background:var(--bg) !important;',
'  font-family:''Inter'',system-ui,sans-serif;',
'  color:var(--ink);',
'}',
'',
'/* ---------- Header banner ---------- */',
'.prediction-card{',
'  background:linear-gradient(120deg,var(--navy-deep) 0%,var(--navy-mid) 55%,var(--blue) 100%);',
'  border-radius:var(--radius-lg);',
'  padding:36px 40px;',
'  color:#fff;',
'  margin-bottom:24px;',
'  box-shadow:0 12px 30px rgba(30,58,95,.25);',
'  position:relative;',
'  overflow:hidden;',
'}',
'.prediction-card::before{',
'  content:"";',
'  position:absolute;',
'  top:-60px; right:-60px;',
'  width:220px; height:220px;',
'  background:radial-gradient(circle,rgba(255,255,255,.10) 0%,transparent 70%);',
'  border-radius:50%;',
'}',
'.prediction-card h1{',
'  font-family:''Sora'',sans-serif;',
'  font-weight:800;',
'  font-size:28px;',
'  letter-spacing:-.01em;',
