'}',
'.verdict-hero.verdict-leave .verdict-text{',
'  text-shadow:0 1px 6px rgba(0,0,0,.25);',
'}',
'',
unistr('/* Rain drops \2014 a brief, light touch reinforcing the somber tone on arrival */'),
'.raindrop{',
'  position:absolute;',
'  top:-16px;',
'  width:2px; height:14px;',
'  border-radius:2px;',
'  background:rgba(255,255,255,.3);',
'  animation:rainFall 1.2s linear forwards;',
'  z-index:0;',
'}',
'',
'/* ----- Animations ----- */',
'@keyframes stayIn{',
'  from{ opacity:0; transform:translateY(14px) scale(.97); }',
'  to{ opacity:1; transform:translateY(0) scale(1); }',
'}',
'@keyframes sparkleTwinkle{',
'  0%,100%{ opacity:0; transform:scale(.5) rotate(0deg); }',
'  50%{ opacity:1; transform:scale(1.1) rotate(20deg); }',
'}',
'@keyframes leaveIn{',
'  from{ opacity:0; transform:translateY(-10px); }',
'  to{ opacity:1; transform:translateY(0); }',
'}',
'@keyframes popBounce{',
'  0%{ transform:scale(.4); opacity:0; }',
'  60%{ transform:scale(1.15); opacity:1; }',
'  100%{ transform:scale(1); }',
'}',
'@keyframes alarmShake{',
'  0%,100%{ transform:translateX(0); }',
'  20%{ transform:translateX(-6px) rotate(-4deg); }',
'  40%{ transform:translateX(6px) rotate(4deg); }',
'  60%{ transform:translateX(-4px) rotate(-2deg); }',
'  80%{ transform:translateX(4px) rotate(2deg); }',
'}',
'@keyframes confettiFall{',
'  to{ transform:translateY(160px) rotate(360deg); opacity:0; }',
'}',
'@keyframes rainFall{',
'  to{ transform:translateY(120px); opacity:0; }',
'}',
'',
'@media (prefers-reduced-motion: reduce){',
'  .verdict-hero.verdict-stay,',
'  .verdict-hero.verdict-leave,',
'  .verdict-hero .verdict-icon,',
'  .verdict-hero .verdict-text,',
'  .verdict-hero .sparkle,',
'  .confetti-piece,',
'  .raindrop{',
'    animation:none !important;',
'  }',
'}',
'',
'@media (max-width:640px){',
'  .verdict-hero{',
'    grid-template-columns:auto 1fr;',
'    padding:14px 16px;',
'  }',
'  .verdict-hero .verdict-icon{ font-size:26px; }',
'  .verdict-hero .verdict-text{ font-size:16px; }',
'}',
'',
'/* ==========================================================================',
unistr('   METRICS GRID \2014 custom-built cards (replaces default plain item rendering)'),
'   ========================================================================== */',
'',
'.metrics-grid{',
'  display:grid;',
'  grid-template-columns:repeat(auto-fit, minmax(150px, 1fr));',
'  gap:16px;',
'  margin-top:8px;',
'}',
'',
'.metric-card{',
'  background:var(--surface);',
'  border:1px solid var(--border);',
'  border-radius:var(--radius-md);',
'  padding:20px;',
'  box-shadow:var(--shadow-card);',
'  transition:transform .18s ease, box-shadow .18s ease;',
'  position:relative;',
'  overflow:hidden;',
'}',
'.metric-card:hover{',
'  transform:translateY(-3px);',
'  box-shadow:0 10px 26px rgba(16,24,40,.10);',
'}',
'.metric-card::before{',
'  content:"";',
'  position:absolute;',
'  top:0; left:0; right:0;',
'  height:3px;',
'  background:var(--blue);',
'}',
'',
'.metric-card--wide{',
'  grid-column:1 / -1;',
'}',
'',
'.metric-icon{',
'  font-size:22px;',
'  margin-bottom:10px;',
'  line-height:1;',
'}',
'',
'.metric-label{',
'  font-family:''Inter'',sans-serif;',
'  font-size:11px;',
'  font-weight:600;',
'  letter-spacing:.07em;',
'  text-transform:uppercase;',
'  color:var(--ink-soft);',
'  margin-bottom:6px;',
'}',
'',
'.metric-value{',
'  font-family:''Sora'',sans-serif;',
'  font-size:20px;',
'  font-weight:700;',
'  color:var(--ink);',
'  line-height:1.3;',
'}',
'',
'.metric-value--mono{',
'  font-family:''JetBrains Mono'',monospace;',
'  font-size:28px;',
'  color:var(--blue);',
'}',
'',
'.metric-value--text{',
'  font-family:''Inter'',sans-serif;',
'  font-size:14.5px;',
'  font-weight:400;',
'  line-height:1.6;',
'  color:var(--ink-soft);',
'}',
'',
unistr('/* Risk-level color coding \2014 brighter, more saturated */'),
'.metric-card.risk-low::before{ background:var(--stay-bright); }',
'.metric-card.risk-low .metric-value{ color:var(--stay); }',
'.metric-card.risk-low{ background:linear-gradient(180deg,#fff 0%,var(--stay-bg) 140%); }',
'',
'.metric-card.risk-medium::before{ background:var(--medium); }',
'.metric-card.risk-medium .metric-value{ color:var(--medium); }',
'.metric-card.risk-medium{ background:linear-gradient(180deg,#fff 0%,var(--medium-bg) 140%); }',
'',
'.metric-card.risk-high::before{ background:var(--leave); }',
'.metric-card.risk-high .metric-value{ color:var(--leave-deep); }',
'.metric-card.risk-high{ background:linear-gradient(180deg,#fff 0%,var(--leave-bg) 140%); }',
'',
'@media (max-width:640px){',
'  .metrics-grid{ grid-template-columns:1fr 1fr; gap:12px; }',
'  .metric-card{ padding:16px; }',
'  .metric-value--mono{ font-size:22px; }',
'}'))
