,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    P.PREDICTION_ID,',
'    E.EMP_NO,',
'    E.FIRST_NAME || '' '' || E.LAST_NAME AS EMPLOYEE_NAME,',
'    E.DEPARTMENT,',
'    P.PREDICTION,',
'    P.RISK_LEVEL,',
'    P.PROBABILITY,',
'    P.MODEL_NAME,',
'    P.PREDICTION_DATE',
'FROM PREDICTIONS P',
'JOIN EMPLOYEE E',
'    ON P.EMPLOYEE_ID = E.EMPLOYEE_ID',
'ORDER BY P.PREDICTION_DATE DESC;'))
