wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(18203358841324961134)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'test123'
,p_static_id=>'test123_1'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    ------------------------------------------------------------',
'    -- Gemini API',
'    ------------------------------------------------------------',
'    l_url VARCHAR2(500) :=',
'        ''https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash:generateContent?key=AQ.Ab8RN6LYPHbAwAkhDYqzxNzyu5nCR0rM5_bzt8Jn6VbUJeqRyQ'';',
'',
'    l_request    CLOB;',
'    l_response   CLOB;',
'    l_prompt     CLOB;',
'    l_ai_json    CLOB;',
'',
'    ------------------------------------------------------------',
'    -- Calculated Metrics',
'    ------------------------------------------------------------',
'    v_salary_difference     NUMBER;',
'    v_calculated_attrition  NUMBER;',
'',
'    ------------------------------------------------------------',
'    -- Employee Variables',
'    ------------------------------------------------------------',
'    v_first_name        EMPLOYEE.FIRST_NAME%TYPE;',
'    v_last_name         EMPLOYEE.LAST_NAME%TYPE;',
'    v_department        EMPLOYEE.DEPARTMENT%TYPE;',
'    v_job_role           EMPLOYEE.JOB_ROLE%TYPE;',
'    v_income             EMPLOYEE.MONTHLY_INCOME%TYPE;',
'    v_years_company      EMPLOYEE.YEARS_AT_COMPANY%TYPE;',
'    v_total_years        EMPLOYEE.TOTAL_WORKING_YEARS%TYPE;',
'    v_years_role         EMPLOYEE.YEARS_IN_CURRENT_ROLE%TYPE;',
'    v_years_promotion    EMPLOYEE.YEARS_SINCE_LAST_PROMOTION%TYPE;',
'    v_performance        EMPLOYEE.PERFORMANCE_RATING%TYPE;',
'    v_job_sat            EMPLOYEE.JOB_SATISFACTION%TYPE;',
'    v_env_sat            EMPLOYEE.ENVIRONMENT_SATISFACTION%TYPE;',
'    v_worklife           EMPLOYEE.WORK_LIFE_BALANCE%TYPE;',
'    v_job_involvement    EMPLOYEE.JOB_INVOLVEMENT%TYPE;',
'    v_training           EMPLOYEE.TRAINING_TIMES_LAST_YEAR%TYPE;',
'    v_num_companies      EMPLOYEE.NUM_COMPANIES_WORKED%TYPE;',
'    v_distance           EMPLOYEE.DISTANCE_FROM_HOME%TYPE;',
'    v_overtime           EMPLOYEE.OVERTIME%TYPE;',
'    v_business_travel    EMPLOYEE.BUSINESS_TRAVEL%TYPE;',
'    v_education          EMPLOYEE.EDUCATION%TYPE;',
'    v_education_field    EMPLOYEE.EDUCATION_FIELD%TYPE;',
'    v_marital            EMPLOYEE.MARITAL_STATUS%TYPE;',
'    v_engagement         EMPLOYEE.ENGAGEMENT_SCORE%TYPE;',
'',
'    ------------------------------------------------------------',
'    -- Employee Profile Variables',
'    ------------------------------------------------------------',
'    v_avg_job_tenure     EMPLOYEE_PROFILE.AVG_PREVIOUS_JOB_TENURE%TYPE;',
'    v_dependents         EMPLOYEE_PROFILE.DEPENDENTS%TYPE;',
'    v_market_salary      EMPLOYEE_PROFILE.CURRENT_MARKET_SALARY%TYPE;',
'    v_salary_gap         EMPLOYEE_PROFILE.SALARY_GAP_PERCENT%TYPE;',
'    v_absenteeism        EMPLOYEE_PROFILE.ABSENTEEISM_RATE%TYPE;',
'    v_manager_feedback   EMPLOYEE_PROFILE.MANAGER_FEEDBACK_SCORE%TYPE;',
'    v_promotion_rate     EMPLOYEE_PROFILE.PROMOTION_RATE%TYPE;',
'    v_attrition_score    EMPLOYEE_PROFILE.ATTRITION_SCORE%TYPE;',
'',
'BEGIN',
'',
'    apex_debug.message(''STEP 0: Process started. P3_EMPLOYEE = '' || :P3_EMPLOYEE);',
'',
'    ------------------------------------------------------------------',
'    -- 1. Fetch employee + profile data',
'    ------------------------------------------------------------------',
'    SELECT',
'        e.first_name, e.last_name, e.department, e.job_role,',
'        e.monthly_income, e.years_at_company, e.total_working_years,',
'        e.years_in_current_role, e.years_since_last_promotion,',
'        e.performance_rating, e.job_satisfaction, e.environment_satisfaction,',
'        e.work_life_balance, e.job_involvement, e.training_times_last_year,',
'        e.num_companies_worked, e.distance_from_home, e.overtime,',
'        e.business_travel, e.education, e.education_field,',
'        e.marital_status, e.engagement_score,',
'        p.avg_previous_job_tenure, p.dependents, p.current_market_salary,',
'        p.salary_gap_percent, p.absenteeism_rate, p.manager_feedback_score,',
'        p.promotion_rate, p.attrition_score',
'    INTO',
'        v_first_name, v_last_name, v_department, v_job_role,',
'        v_income, v_years_company, v_total_years,',
'        v_years_role, v_years_promotion,',
'        v_performance, v_job_sat, v_env_sat,',
'        v_worklife, v_job_involvement, v_training,',
'        v_num_companies, v_distance, v_overtime,',
'        v_business_travel, v_education, v_education_field,',
'        v_marital, v_engagement,',
'        v_avg_job_tenure, v_dependents, v_market_salary,',
'        v_salary_gap, v_absenteeism, v_manager_feedback,',
'        v_promotion_rate, v_attrition_score',
'    FROM employee e',
'    JOIN employee_profile p',
'        ON e.employee_id = p.employee_id',
'    WHERE e.employee_id = :P3_EMPLOYEE;',
'',
'    apex_debug.message(''STEP 1: Employee fetched OK. Name = '' || v_first_name || '' '' || v_last_name);',
'',
'    ------------------------------------------------------------------',
'    -- 2. Calculate Salary Difference',
'    ------------------------------------------------------------------',
'    v_salary_difference := v_market_salary - v_income;',
'',
'    ------------------------------------------------------------------',
'    -- 3. Calculate Rule-Based Attrition Score',
'    ------------------------------------------------------------------',
'    v_calculated_attrition := 0;',
'',
'    IF v_job_sat <= 2 THEN',
'        v_calculated_attrition := v_calculated_attrition + 15;',
'    END IF;',
'',
'    IF v_worklife <= 2 THEN',
'        v_calculated_attrition := v_calculated_attrition + 15;',
'    END IF;',
'',
'    IF UPPER(v_overtime) = ''YES'' THEN',
'        v_calculated_attrition := v_calculated_attrition + 15;',
'    END IF;',
'',
'    IF v_years_promotion >= 3 THEN',
'        v_calculated_attrition := v_calculated_attrition + 10;',
'    END IF;',
'',
'    IF v_engagement < 60 THEN',
'        v_calculated_attrition := v_calculated_attrition + 20;',
'    END IF;',
'',
'    IF v_performance <= 2 THEN',
'        v_calculated_attrition := v_calculated_attrition + 10;',
'    END IF;',
'',
'    IF v_absenteeism > 10 THEN',
'        v_calculated_attrition := v_calculated_attrition + 10;',
'    END IF;',
'',
'    IF v_salary_gap < -10 THEN',
'        v_calculated_attrition := v_calculated_attrition + 10;',
'    END IF;',
'',
'    IF v_calculated_attrition > 100 THEN',
'        v_calculated_attrition := 100;',
'    END IF;',
'',
'    apex_debug.message(''STEP 2: Attrition score calculated = '' || v_calculated_attrition);',
'',
'    ------------------------------------------------------------------',
'    -- 4. Build AI Prompt',
'    ------------------------------------------------------------------',
'    l_prompt :=',
'''You are a Senior HR Analytics AI.',
'',
'Your task is to predict employee attrition using HR analytics.',
'',
'Below is the employee profile.',
'',
'Employee Name:',
'''||v_first_name||'' ''||v_last_name||''',
'',
'Department:',
'''||v_department||''',
'',
'Job Role:',
'''||v_job_role||''',
'',
'Monthly Salary:',
'''||v_income||''',
'',
'Market Salary:',
'''||v_market_salary||''',
'',
'Salary Gap (%):',
'''||v_salary_gap||''',
'',
'Salary Difference:',
'''||v_salary_difference||''',
'',
'Years at Company:',
'''||v_years_company||''',
'',
'Total Experience:',
'''||v_total_years||''',
'',
'Average Previous Job Tenure:',
'''||v_avg_job_tenure||''',
'',
'Number of Previous Companies:',
'''||v_num_companies||''',
'',
'Dependents:',
'''||v_dependents||''',
'',
'Performance Rating:',
'''||v_performance||''',
'',
'Job Satisfaction:',
'''||v_job_sat||''',
'',
'Environment Satisfaction:',
'''||v_env_sat||''',
'',
'Work Life Balance:',
'''||v_worklife||''',
'',
'Job Involvement:',
'''||v_job_involvement||''',
'',
'Promotion Rate:',
'''||v_promotion_rate||''',
'',
'Years Since Promotion:',
'''||v_years_promotion||''',
'',
'Training Last Year:',
'''||v_training||''',
'',
'Distance From Home:',
'''||v_distance||''',
'',
'Business Travel:',
'''||v_business_travel||''',
'',
'Overtime:',
'''||v_overtime||''',
'',
'Marital Status:',
'''||v_marital||''',
'',
'Engagement Score:',
'''||v_engagement||''',
'',
'Manager Feedback:',
'''||v_manager_feedback||''',
'',
'Absenteeism Rate:',
'''||v_absenteeism||''',
'',
'Oracle Calculated Attrition Score:',
'''||v_calculated_attrition||''',
'',
'Analyse every factor carefully.',
'',
'Return ONLY valid JSON.',
'',
'{',
'"prediction":"Stay or Leave",',
'"probability":85,',
'"risk_level":"Low Medium High",',
'"confidence":"Very High",',
'"reason":"Explain in 2-3 sentences why this employee may stay or leave.",',
'"recommendation":"Professional HR recommendation."',
'}'';',
'',
'    apex_debug.message(''STEP 3: Prompt built. Length = '' || DBMS_LOB.GETLENGTH(l_prompt));',
'',
'    ------------------------------------------------------------------',
'    -- 5. Build Request Body',
'    ------------------------------------------------------------------',
'    l_request :=',
'        ''{',
' "contents":[',
'   {',
'     "parts":[',
'       {',
'         "text":''||apex_json.stringify(l_prompt)||''',
'       }',
'     ]',
'   }',
' ]',
'}'';',
'',
'    apex_debug.message(''STEP 4: Request body built. Length = '' || DBMS_LOB.GETLENGTH(l_request));',
'',
'    ------------------------------------------------------------------',
'    -- 6. HTTP Headers',
'    ------------------------------------------------------------------',
'    apex_web_service.g_request_headers.delete;',
'    apex_web_service.g_request_headers(1).name  := ''Content-Type'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'',
'    ------------------------------------------------------------------',
'    -- 7. Call Gemini',
'    ------------------------------------------------------------------',
'    apex_debug.message(''STEP 5: Calling Gemini API now...'');',
'',
'    l_response := apex_web_service.make_rest_request(',
'        p_url         => l_url,',
'        p_http_method => ''POST'',',
'        p_body        => l_request',
'    );',
'',
'    apex_debug.message(''STEP 6: Gemini responded. Status code = '' || apex_web_service.g_status_code);',
'    apex_debug.message(''STEP 6b: Raw response (first 3000 chars) = '' || DBMS_LOB.SUBSTR(l_response, 3000, 1));',
'',
'    ------------------------------------------------------------------',
'    -- 8. Parse Gemini Response Envelope',
'    ------------------------------------------------------------------',
'    apex_json.parse(l_response);',
'',
'    l_ai_json := apex_json.get_clob(',
'        p_path => ''candidates[%d].content.parts[%d].text'',',
'        p0     => 1,',
'        p1     => 1',
'    );',
'',
'    l_ai_json := REPLACE(l_ai_json, ''```json'', '''');',
'    l_ai_json := REPLACE(l_ai_json, ''```'', '''');',
'',
'    apex_debug.message(''STEP 7: Extracted AI JSON text = '' || DBMS_LOB.SUBSTR(l_ai_json, 3000, 1));',
'',
'    ------------------------------------------------------------------',
'    -- 9. Parse the Model''s JSON Answer',
'    ------------------------------------------------------------------',
'    apex_json.parse(l_ai_json);',
'',
'    :P3_PREDICTION     := apex_json.get_varchar2(''prediction'');',
'    :P3_PROBABILITY    := apex_json.get_number(''probability'');',
'    :P3_RISK_LEVEL      := apex_json.get_varchar2(''risk_level'');',
'    :P3_CONFIDENCE      := apex_json.get_varchar2(''confidence'');',
'    :P3_REASON          := apex_json.get_varchar2(''reason'');',
'    :P3_RECOMMENDATION  := apex_json.get_varchar2(''recommendation'');',
'    :P3_MODEL           := ''Gemini 3.5 Flash'';',
'',
'    apex_debug.message(''STEP 8: Items set. Prediction = '' || :P3_PREDICTION || '', Probability = '' || :P3_PROBABILITY);',
'',
'    ------------------------------------------------------------------',
'    -- 10. Save Prediction',
'    ------------------------------------------------------------------',
'    INSERT INTO PREDICTIONS',
'    (',
'        EMPLOYEE_ID,',
'        PREDICTION,',
'        PROBABILITY,',
'        RISK_LEVEL,',
'        MODEL_NAME',
'    )',
'    VALUES',
'    (',
'        :P3_EMPLOYEE,',
'        :P3_PREDICTION,',
'        :P3_PROBABILITY,',
'        :P3_RISK_LEVEL,',
'        :P3_MODEL',
'    );',
'',
'    apex_debug.message(''STEP 9: Insert into PREDICTIONS complete. Process finished successfully.'');',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        apex_debug.message(''ERROR: NO_DATA_FOUND - no matching employee/profile row for employee_id = '' || :P3_EMPLOYEE);',
'        raise_application_error(',
