,p_warn_on_unsaved_changes=>'N'
,p_first_item=>'AUTO_FIRST_ITEM'
,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* ===============================',
unistr('   AI LOGIN PAGE \2014 Professional, compact'),
'================================ */',
'body,',
'.t-LoginPage{',
'    background:',
'    radial-gradient(circle at top left, rgba(71,85,105,.25) 0%, transparent 40%),',
'    radial-gradient(circle at bottom right, rgba(30,41,59,.4) 0%, transparent 40%),',
'    linear-gradient(135deg,#0b1120,#111827,#1e293b);',
'    min-height:100vh;',
'    overflow:hidden;',
'}',
'',
'body::before,',
'body::after{',
'    content:"";',
'    position:fixed;',
'    width:280px;',
'    height:280px;',
'    border-radius:50%;',
'    filter:blur(120px);',
'    opacity:.16;',
'    z-index:0;',
'}',
'body::before{ background:#334155; top:-100px; left:-100px; }',
'body::after{ background:#1e40af; right:-100px; bottom:-100px; }',
'',
unistr('/* Login Card \2014 shorter */'),
'.t-Login-region{',
'    position:relative;',
'    z-index:2;',
'    width:360px;',
'    max-width:90vw;',
'    border-radius:14px;',
'    background:rgba(15,23,42,.65);',
'    backdrop-filter:blur(16px);',
'    -webkit-backdrop-filter:blur(16px);',
'    border:1px solid rgba(255,255,255,.08);',
'    box-shadow:0 20px 50px rgba(0,0,0,.45);',
'    padding:22px 28px;',
'}',
'',
'.t-Login-logo img{',
'    width:44px;',
'    border-radius:8px;',
'    box-shadow:0 8px 20px rgba(0,0,0,.3);',
'}',
'',
'.t-Login-title{',
'    color:#f1f5f9;',
'    font-size:19px;',
'    font-weight:600;',
'    margin-top:8px;',
'    margin-bottom:2px;',
'    letter-spacing:-.01em;',
'}',
'.t-Login-subTitle{',
'    color:rgba(226,232,240,.6);',
'    font-size:12.5px;',
'    margin-bottom:10px;',
'}',
'',
'.apex-item-text{',
'    height:40px;',
'    border-radius:8px!important;',
'    background:rgba(255,255,255,.96)!important;',
'    border:1px solid rgba(255,255,255,.1)!important;',
'    padding-left:12px;',
'    font-size:14px;',
'    color:#0f172a!important;',
'    margin-bottom:6px;',
'}',
'.apex-item-text:focus{',
'    box-shadow:0 0 0 3px rgba(100,116,139,.35)!important;',
'    outline:none!important;',
'}',
'',
unistr('/* Button \2014 explicitly forced visible */'),
'.t-Button--hot,',
'button.t-Button--hot,',
'.t-Button.t-Button--hot{',
'    display:inline-flex!important;',
'    visibility:visible!important;',
'    opacity:1!important;',
'    width:100%;',
'    height:42px;',
'    border-radius:8px;',
'    border:none!important;',
'    background:#2563eb!important;',
'    color:#ffffff!important;',
'    font-size:14px;',
'    font-weight:600;',
'    letter-spacing:.01em;',
'    transition:background .2s ease, transform .2s ease;',
'    box-shadow:0 8px 20px rgba(37,99,235,.3);',
'    margin-top:4px;',
'}',
'.t-Button--hot:hover{',
'    background:#1d4ed8!important;',
'    transform:translateY(-1px);',
'}',
'.t-Button--hot:active{ transform:translateY(0); }',
'',
'.t-Form-label,',
'label{',
'    color:rgba(226,232,240,.85)!important;',
'    font-size:12.5px;',
'}',
'',
'.t-Login-footer{',
'    color:rgba(148,163,184,.55);',
'    font-size:11.5px;',
'    margin-top:10px;',
'}',
'/* Target only the direct parent that wraps the input+icon, not the label */',
'.t-Login-region .apex-item-text-icon,',
'.t-Login-region .a-Input-container,',
'.t-Login-region span:has(> .apex-item-text){',
'    position:relative!important;',
'    display:block!important;',
'}',
'',
'.t-Login-region .t-Icon,',
'.t-Login-region .a-Icon,',
'.t-Login-region i[class*="fa-"]{',
'    position:absolute!important;',
'    top:22px!important;',
'    left:14px!important;',
'    transform:translateY(-50%)!important;',
'    margin:0!important;',
'    z-index:5;',
'}',
'',
'.t-Login-region .apex-item-text{',
'    padding-left:42px!important;',
'    box-sizing:border-box!important;',
'}'))
